-- Municipalities and arrondissements, loaded from municipality.csv (generated by tools/fetch-municipalities.mjs).
-- Parents (cities) are inserted first, then arrondissements resolve parent_municipality_id by INSEE code.
-- Idempotent: rows whose insee_code already exists are left unchanged.
BEGIN;

CREATE TEMP TABLE municipality_import (
  insee_code char(5) NOT NULL,
  name text NOT NULL,
  department_code varchar(3) NOT NULL,
  population int NOT NULL,
  lat double precision NOT NULL,
  lng double precision NOT NULL,
  parent_insee_code char(5)
) ON COMMIT DROP;

\copy municipality_import FROM '/workspace/db/seeds/reference/municipality.csv' WITH (FORMAT csv, HEADER true)

INSERT INTO municipality (insee_code, name, department_code, population, center)
SELECT insee_code, name, department_code, population, ST_SetSRID(ST_MakePoint(lng, lat), 4326)::geography
FROM municipality_import
WHERE parent_insee_code IS NULL
ON CONFLICT DO NOTHING;

INSERT INTO municipality (insee_code, name, department_code, population, center, parent_municipality_id)
SELECT i.insee_code, i.name, i.department_code, i.population,
       ST_SetSRID(ST_MakePoint(i.lng, i.lat), 4326)::geography, p.id
FROM municipality_import i
JOIN municipality p ON p.insee_code = i.parent_insee_code
WHERE i.parent_insee_code IS NOT NULL
ON CONFLICT DO NOTHING;

COMMIT;
